//! Parsing of RPG Maker's `js/plugins.js`.
//!
//! The file has the shape:
//! ```js
//! // Generated by RPG Maker.
//! // Do not edit this file directly.
//! var $plugins =
//! [
//! {"name":"X","status":true,"description":"...","parameters":{...}},
//! ...
//! ];
//! ```
//! The array itself is valid JSON, so instead of fragile regexes we extract the
//! `[ ... ]` region and parse it with serde_json. This is far more robust than
//! the v1 regex approach and preserves the exact load order.

use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
pub struct PluginEntry {
    pub name: String,
    #[serde(default)]
    pub status: bool,
    #[serde(default)]
    pub description: String,
}

#[derive(Debug)]
pub enum ParseError {
    NoArray,
    Json(String),
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseError::NoArray => write!(f, "could not find the $plugins array in plugins.js"),
            ParseError::Json(e) => write!(f, "failed to parse plugins.js as JSON: {e}"),
        }
    }
}
impl std::error::Error for ParseError {}

/// Parse the full content of a `plugins.js` file into an ordered list of entries.
pub fn parse_plugins_js(content: &str) -> Result<Vec<PluginEntry>, ParseError> {
    let start = content.find('[').ok_or(ParseError::NoArray)?;
    let end = content.rfind(']').ok_or(ParseError::NoArray)?;
    if end <= start {
        return Err(ParseError::NoArray);
    }
    let array_src = &content[start..=end];
    serde_json::from_str::<Vec<PluginEntry>>(array_src)
        .map_err(|e| ParseError::Json(e.to_string()))
}

impl PluginEntry {
    /// Expected on-disk filename of this plugin inside `js/plugins/`.
    pub fn file_name(&self) -> String {
        format!("{}.js", self.name)
    }
}

/// The enabled plugins, in load order.
pub fn enabled_in_order(entries: &[PluginEntry]) -> Vec<&PluginEntry> {
    entries.iter().filter(|p| p.status).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"// Generated by RPG Maker.
// Do not edit this file directly.
var $plugins =
[
{"name":"@XDEV_MZ","status":true,"description":"Dev","parameters":{}},
{"name":"VisuMZ_0_CoreEngine","status":false,"description":"[Tier 0]","parameters":{"a":"{\"nested\":\"[x]\"}"}},
{"name":"PKD_AnimaX","status":true,"description":"anim","parameters":{}}
];
"#;

    #[test]
    fn parses_order_and_status() {
        let p = parse_plugins_js(SAMPLE).unwrap();
        assert_eq!(p.len(), 3);
        assert_eq!(p[0].name, "@XDEV_MZ");
        assert!(p[0].status);
        assert!(!p[1].status);

        let enabled = enabled_in_order(&p);
        assert_eq!(enabled.len(), 2);
        assert_eq!(enabled[0].name, "@XDEV_MZ");
        assert_eq!(enabled[1].name, "PKD_AnimaX");
        assert_eq!(enabled[1].file_name(), "PKD_AnimaX.js");
    }

    #[test]
    fn handles_nested_json_in_parameters() {
        // The tricky part of real plugins.js: parameters contain escaped JSON
        // strings with brackets. serde handles this; a naive bracket scan would not.
        let p = parse_plugins_js(SAMPLE).unwrap();
        assert_eq!(p[1].name, "VisuMZ_0_CoreEngine");
    }

    #[test]
    fn rejects_garbage() {
        assert!(parse_plugins_js("no array here").is_err());
    }
}
